INSERT INTO pyq_collections (id, slug, subject, title, exam_paper, year, is_premium, question_count, sort_order)
VALUES ('12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 'upsc-anthropology-optional-paper-2-pyq', 'anthropology', 'UPSC Anthropology Optional Paper II — PYQ & Model Answers (2023)', 'paper-2', 2023, true, 28, 2);

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('61a9fca7-bb1d-4bb6-96f3-746181e7b8db', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 1, 'A', '1(a)', 10, 150, 'Material culture and archaeology');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('61a9fca7-bb1d-4bb6-96f3-746181e7b8db', 'Material culture -- the tangible objects a society produces and uses (tools, pottery, dwellings, ornaments, monuments) -- is archaeology''s primary evidentiary base, since past societies without written records can be reconstructed almost entirely from what they made, used and discarded.

Interdependence: archaeology supplies the excavation, stratigraphic dating and typological method needed to sequence and contextualize material remains, while material culture supplies the actual data (technology, subsistence, exchange, ritual) that archaeological interpretation works on. V. Gordon Childe''s culture-historical approach treated recurring assemblages of material traits as markers of distinct ''archaeological cultures'' (e.g., Harappan pottery/seal assemblages); processual archaeology (Lewis Binford) instead reads material culture as evidence of past behavioural systems and adaptation, not just chronological markers.

Indian illustration: Harappan seals, weights and standardized brick sizes reveal administrative and craft organization; megalithic burial goods in peninsular India reveal Iron Age social ranking. Together, material culture and archaeology form a mutually constitutive method for reconstructing prehistoric and historic human life.', 'Naming both a culture-historical (Childe) and processual (Binford) framing of how material culture is interpreted, plus one concrete Indian example, distinguishes a complete answer from a bare definition.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section A, Q1(a). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('5dacec98-0f53-4590-9d57-cb35309db462', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 2, 'A', '1(b)', 10, 150, 'Interface between Purushartha and Ashrama');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('5dacec98-0f53-4590-9d57-cb35309db462', 'Purushartha (the four aims of human life -- Dharma, Artha, Kama, Moksha) and Ashrama (the four life-stages -- Brahmacharya, Grihastha, Vanaprastha, Sannyasa) together constitute classical Hindu social philosophy''s integrated life-course model, in which each stage is normatively oriented toward a corresponding weighting of the four aims.

Interface: the Brahmacharya (celibate student) stage emphasizes Dharma -- acquiring knowledge and disciplined conduct; Grihastha (householder) emphasizes Artha and Kama -- earning livelihood, raising family, within dharmic bounds, and is considered the stage that sustains the other three (since householders support students, ascetics and renunciants); Vanaprastha (forest-dweller/retiree) marks gradual detachment, transitioning toward Moksha; Sannyasa (renunciant) is wholly oriented to Moksha, having relinquished Artha and Kama entirely.

Significance: this interface reflects a structured life-course theory balancing material and spiritual pursuits sequentially rather than simultaneously, providing an indigenous Indological framework for understanding social role-transition, obligation and the relationship between individual life-stage and collective social reproduction -- though in practice, especially in modern urban India, the Ashrama-Purushartha sequence is followed only loosely, if at all.', 'The answer should map each Ashrama stage explicitly onto its corresponding dominant Purushartha(s) rather than describing the two schemes side by side without linking them -- that mapping is the actual ''interface'' being asked for.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section A, Q1(b). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('a457426b-b6cf-49c8-a2b3-e1e07e374e22', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 3, 'A', '1(c)', 10, 150, 'Jajmani system: continuity and change');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('a457426b-b6cf-49c8-a2b3-e1e07e374e22', 'The jajmani system is a traditional rural Indian institution of hereditary, reciprocal exchange between landowning patron castes (jajmans) and service/artisan castes (kamins/praja) -- barbers, potters, carpenters, washermen -- who provide fixed goods/services in exchange for a customary share of the harvest or fixed payment, embedded in caste hierarchy and studied extensively by William Wiser (who coined the term) and later critically examined by scholars like T.S. Epstein and Pauline Kolenda.

Continuity: in remote/rural areas the system persists in modified form, still regulating some caste-based service obligations and reinforcing village-level economic interdependence and ritual status hierarchy.

Change: the system has substantially eroded due to land reforms altering landholding patterns, growth of a cash/market economy replacing produce-based payment, rural-to-urban migration providing kamins alternative livelihoods, spread of education reducing willingness to perform hereditary occupational roles, and Green Revolution-driven agricultural commercialization. Scholars increasingly note the jajmani system today survives more as diluted, negotiable, semi-monetized arrangements than the rigid hereditary system Wiser originally described, reflecting broader detribalization/de-agrarianization of the rural caste economy.', 'Naming Wiser as originator and citing land reform/monetization/education as the concrete drivers of change (not a vague ''modernization has changed it'' statement) is the expected substantiation.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section A, Q1(c). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('2598506d-4471-41e2-893f-8d6c6326d179', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 4, 'A', '1(d)', 10, 150, 'Prehistoric rock arts from Uttarakhand');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('2598506d-4471-41e2-893f-8d6c6326d179', 'Uttarakhand''s Kumaon and Garhwal regions preserve significant prehistoric rock-art sites, most notably Lakhudiyar (near Almora), along with sites like Petshal and Futsil Rong, generally dated across a broad span from Mesolithic through later prehistoric/protohistoric periods based on comparative stylistic and superimposition analysis.

Features: paintings executed in ochre/red, white and occasionally black pigment on rock-shelter surfaces, depicting human figures (often in dancing or group postures), animals (deer, elephants), geometric motifs (dots, wavy lines, comb-like patterns), and handprints -- Lakhudiyar''s imagery includes distinctive tailed anthropomorphic figures interpreted by some scholars as ritual/shamanic representations.

Significance: these paintings provide rare direct evidence of prehistoric symbolic behaviour, social organization (group dance/ritual scenes) and human-animal relations in the Himalayan foothills, complementing lithic evidence from the region; superimposed layers of different artistic styles at some sites suggest successive occupation phases across different prehistoric periods. They remain understudied and inadequately protected relative to better-known central Indian rock-art complexes like Bhimbetka, making their systematic documentation and conservation an ongoing concern for Indian prehistoric archaeology.', 'Lakhudiyar should be named specifically as the flagship site; noting the tailed/anthropomorphic dancing-figure motif and comparing (even briefly) to Bhimbetka situates Uttarakhand''s rock art within the broader Indian prehistoric-art record expected of a complete answer.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section A, Q1(d). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('b98f7acc-9cff-49ab-8ee5-62da44b35536', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 5, 'A', '1(e)', 10, 150, 'Religious pluralism and social solidarity');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('b98f7acc-9cff-49ab-8ee5-62da44b35536', 'Religious pluralism -- the coexistence and mutual recognition of multiple religious traditions within a society, without one imposing dominance -- has an ambivalent relationship with social solidarity (Durkheim''s shared collective conscience binding a society together).

Supportive relationship: pluralism can enhance solidarity at the level of the wider (national/civic) society by fostering a shared ethic of tolerance, secular constitutional values, and cross-cutting interactions (interfaith festivals, shared civic spaces) that bind diverse religious communities into a common political community -- India''s constitutional secularism and syncretic traditions (Sufi-Bhakti movements, shared shrines venerated across faiths) illustrate pluralism actively generating cross-community solidarity.

Tension with solidarity: Durkheim''s classical model presupposed a single shared conscience collective for solidarity; genuine pluralism can also produce parallel, insulated religious solidarities (strong bonding within each community) rather than a single integrated bridging solidarity, and can be exploited for communal polarization and conflict where pluralism is managed poorly (communal riots, contested religious sites).

Conclusion: religious pluralism strengthens social solidarity only when institutionally managed through genuine tolerance, legal even-handedness and cross-community engagement -- absent that, plural religious identities can as easily fragment solidarity as reinforce it.', 'The answer should explicitly engage both directions of the relationship (pluralism can build bridging solidarity via tolerance/shared civic life, but can also entrench separate bonding solidarities or fuel conflict) rather than assuming pluralism straightforwardly produces harmony.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section A, Q1(e). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('9d21de23-6300-467c-a7c1-8e03317ecf93', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 6, 'A', '2(a)', 20, 350, '"Tribes are backward Hindus." Critically comment with reference to the contributions of G.S. Ghurye.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('9d21de23-6300-467c-a7c1-8e03317ecf93', 'Introduction: G.S. Ghurye, a foundational figure of Indian sociology/social anthropology, controversially argued in The Aborigines -- So-Called -- and Their Future (1943) that India''s tribes were not fundamentally distinct from Hindu society but were ''backward Hindus,'' i.e., segments of the same broad Hindu civilizational continuum that had, for various historical and geographical reasons, remained less integrated and less ''advanced.''

Ghurye''s argument: he emphasized cultural and religious continuities between tribal and Hindu practices (worship of similar deities in localized form, overlap in ritual and belief), rejected the colonial administrative-anthropological tendency (notably associated with Verrier Elwin''s early ''isolationist'' position) to treat tribes as wholly separate, primitive ''noble savage'' populations requiring protective isolation, and instead advocated integrationist policy -- gradual assimilation of tribes into mainstream Hindu society via education, land reform and administrative integration, viewing separate tribal reserves/protection as counter-productive and patronizing.

Critique of Ghurye''s position: (i) it substantially understates the genuine cultural, linguistic, religious (animism, totemism) and social-organizational distinctiveness of tribal societies, collapsing real difference into a homogenizing Hindu framework; (ii) it reflects an upper-caste Brahmanical lens that treats Hindu civilization as the normative center against which tribes are measured as ''backward,'' echoing colonial evolutionary hierarchy-thinking even while opposing colonial isolationism; (iii) it underplays tribes'' historical autonomy, resistance movements (Santhal, Munda rebellions) and distinct political institutions predating and independent of Hindu integration; (iv) Elwin and later scholars (Christoph von Furer-Haimendorf) countered with a middle path -- neither full isolation nor forced assimilation, but a ''via media'' preserving tribal autonomy and culture while extending selective development benefits, which substantially shaped India''s actual post-independence Fifth/Sixth Schedule constitutional protections.

Contemporary assessment: the isolation-vs-assimilation (Elwin-Ghurye) debate remains foundational to Indian tribal policy discourse; most contemporary anthropologists reject Ghurye''s ''backward Hindu'' framing as empirically reductive and ideologically loaded, while acknowledging genuine historical overlap and interaction between tribal and Hindu communities at India''s cultural margins (Sanskritization processes among some tribal groups).

Conclusion: Ghurye''s ''backward Hindu'' thesis, while historically influential in shaping integrationist tribal policy debate, is critically assessed today as understating tribal distinctiveness and reflecting a Hindu-normative bias later substantially corrected by the Elwin-inspired ''via media'' approach embedded in India''s constitutional tribal protections.', 'The Ghurye-Elwin isolation-vs-assimilation debate is the essential frame; naming Elwin''s counter-position and the eventual ''via media'' policy compromise (reflected in Fifth/Sixth Schedule protections) is necessary for full marks on a ''critically comment'' question.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section A, Q2(a). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('de654bd2-b194-4fba-832a-acb12b8ffa1d', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 7, 'A', '2(b)', 15, 250, '"Indus Valley was the first settlement of the big civilization." Comment critically.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('de654bd2-b194-4fba-832a-acb12b8ffa1d', 'The claim that the Indus Valley Civilization (IVC, c. 3300-1300 BCE, mature phase c. 2600-1900 BCE) was ''the first settlement of the big civilization'' requires critical qualification rather than acceptance at face value.

What is accurate: the IVC was indeed one of the world''s earliest urban civilizations, contemporaneous with (not preceding) ancient Egypt and Mesopotamia, and was geographically the largest of the three Bronze Age riverine civilizations, spanning parts of present-day Pakistan and northwest India, with over 1,000 known sites. It displayed remarkably advanced urban planning (grid layouts, standardized burnt-brick sizing at Mohenjo-daro and Harappa), sophisticated drainage/sanitation systems unmatched by its contemporaries, standardized weights and measures, and long-distance trade (Mesopotamian records mention ''Meluhha,'' widely identified with the Indus region).

What is inaccurate/needs qualification: it was not the first civilization chronologically -- Mesopotamian urbanism (Uruk period) and Egyptian state formation both predate or are broadly contemporaneous with IVC''s earliest urban phase, so ''first'' is not defensible; it also was not a single monolithic ''settlement'' but a network of numerous cities and towns (Mohenjo-daro, Harappa, Dholavira, Rakhigarhi, Lothal) sharing common material culture, not one settlement.

Conclusion: the IVC is accurately characterized as one of the world''s earliest, largest and most sophisticated Bronze Age urban civilizations, but the specific claim of being ''first'' is a factual overstatement -- its true distinction lies in its unmatched geographic scale, planning sophistication and continuing debates (Rakhigarhi aDNA evidence) about its indigenous developmental depth, not temporal priority.', 'The answer must explicitly correct the ''first'' claim by naming contemporaneous/earlier Mesopotamian and Egyptian urbanism, while crediting the IVC''s genuine distinguishing features (scale, planning, sanitation) -- a purely descriptive praise-only answer misses the ''comment critically'' instruction.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section A, Q2(b). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('0bba0e83-b427-4e7b-a26a-81eddbbbfb8f', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 8, 'A', '2(c)', 15, 250, 'Discuss the basic tenets of Jainism and its impact on Indian society.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('0bba0e83-b427-4e7b-a26a-81eddbbbfb8f', 'Jainism, founded/systematized by Mahavira (24th Tirthankara, 6th century BCE) as a shramanic tradition alongside early Buddhism, rests on core ethical-philosophical tenets: Ahimsa (non-violence toward all living beings, its central and most rigorously practiced principle), Satya (truthfulness), Asteya (non-stealing), Brahmacharya (chastity/self-restraint), and Aparigraha (non-possession/non-attachment); philosophically, Anekantavada (many-sidedness of truth, no single viewpoint is absolute) and its linguistic expression Syadvada (conditional predication) underpin Jain epistemology''s pluralistic tolerance of differing perspectives.

Impact on Indian society: (i) Ahimsa''s influence extended far beyond Jain communities into wider Indian ethical culture, notably shaping vegetarianism norms in parts of India and directly influencing Gandhi''s philosophy of non-violent resistance (satyagraha); (ii) Jain merchant and trading communities (historically significant in Gujarat, Rajasthan, Karnataka) built extensive networks of trade, banking and philanthropy, funding temple architecture, manuscript libraries and educational institutions; (iii) Jain literature contributed substantially to the development of Prakrit and regional-language literary traditions; (iv) Jainism''s rejection of Vedic ritual authority and caste-based sacrificial religion offered a historically significant heterodox challenge to Brahmanical orthodoxy, contributing to India''s long tradition of internal religious pluralism and reform; (v) Jain temple architecture (Dilwara temples, Shravanabelagola''s Gomateshvara statue) forms a major strand of Indian art-historical heritage.

Conclusion: Jainism''s ethical core (Ahimsa, Anekantavada) has left an impact on Indian society disproportionate to its numerically small following, shaping ethics, commerce, art and reformist political thought across two and a half millennia.', 'All five core vows (Ahimsa, Satya, Asteya, Brahmacharya, Aparigraha) plus Anekantavada/Syadvada should be named; the Gandhi-satyagraha linkage to Ahimsa is the standard, expected ''impact on Indian society'' connection.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section A, Q2(c). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('8a10d213-ceac-4aac-9056-28f00b93c50b', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 9, 'A', '3(a)', 20, 350, '"Sanskritization is a culture-bound concept." Critically comment to assess the strength and limitation of this concept in developing a theoretical framework to study social change.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('8a10d213-ceac-4aac-9056-28f00b93c50b', 'Introduction: Sanskritization, coined by M.N. Srinivas in his study of the Coorgs (1952) and elaborated in Social Change in Modern India (1966), describes the process by which a lower caste or tribal group adopts the customs, rituals, ideology and lifestyle of a locally dominant ''twice-born''/higher caste, seeking to claim higher social status within the caste hierarchy over a generation or two.

Culture-bound nature: the concept is explicitly rooted in the specific Indian caste-hierarchy context -- it presupposes a graded, hierarchically ranked social order in which upward mobility is achieved through emulation of a locally-dominant caste''s ritual status markers (vegetarianism, teetotalism, particular deity worship, specific life-cycle rituals) rather than through structural/economic mobility alone, making it not straightforwardly transferable to societies organized around different stratification logics (class-based Western societies, for instance).

Strengths: (i) provided the first systematic, empirically-grounded (fieldwork-based) framework explaining endogenous social mobility and change within the Indian caste system, correcting earlier colonial-administrative and textual-Indological views of caste as a rigid, unchanging structure; (ii) demonstrated agency among lower castes/tribes as active participants in status negotiation, not passive recipients of a fixed hierarchy; (iii) usefully distinguished from ''Westernization'' (Srinivas''s parallel concept for change via contact with Western culture/institutions), giving Indian sociology two distinct, empirically groundable vocabularies for analyzing different change processes simultaneously; (iv) generated substantial comparative fieldwork testing the concept across regions (Srinivas''s own Coorg study, McKim Marriott''s and others'' village studies), refining and regionally qualifying it.

Limitations: (i) as a culture-bound concept, it has limited cross-cultural theoretical portability outside caste-organized societies; (ii) it privileges ritual/status mobility while underplaying economic and political power as independent, sometimes more decisive, drivers of mobility; (iii) it assumes the existence of a stable ''dominant caste'' reference point that Sanskritizing groups emulate, which may not hold uniformly across all regions or eras; (iv) critics (including later Srinivas revisions) note the model can understate resistance to and rejection of Sanskritization by groups asserting distinct, non-Hindu or explicitly anti-caste identities (Ambedkarite conversion to Buddhism as a directly opposed mobility strategy) rather than emulation.

Conclusion: Sanskritization remains a genuinely powerful, India-specific framework for theorizing endogenous caste-based social mobility, but its explicit rootedness in caste-hierarchy logic is simultaneously its defining strength (empirical fit to the Indian context) and its central limitation (restricted general theoretical applicability beyond that context).', 'The Srinivas-Coorg origin and the explicit Sanskritization/Westernization distinction are non-negotiable content; citing Ambedkarite Buddhist conversion as a counter-strategy to Sanskritization (rejection rather than emulation) is the expected sophisticated limitation point for full marks.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section A, Q3(a). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('9c0c21c0-164e-42ae-8dd6-18a1b2884f8c', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 10, 'A', '3(b)', 15, 250, 'Was Mesolithic culture the first step towards sedentary way of life? Illustrate your answer by citing suitable examples.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('9c0c21c0-164e-42ae-8dd6-18a1b2884f8c', 'The Mesolithic (India, c. 10,000-4,000 years ago) is best understood as a transitional phase toward, rather than the outright first achievement of, sedentary life -- it represents the first significant movement away from purely mobile Paleolithic foraging, without yet reaching the fully settled agricultural village life of the Neolithic.

Evidence of increasing settlement tendency: Mesolithic sites like Bagor (Rajasthan) show repeated, long-term occupation of the same location with associated burials, suggesting semi-sedentary or seasonally-recurring settlement rather than constant mobility; Sarai Nahar Rai and Mahadaha (Ganga plain, Uttar Pradesh) show substantial cemetery areas implying attachment to a fixed locale across generations; broad-spectrum foraging (fishing, small-game hunting, plant gathering) around resource-rich riverine locations reduced the need for the wide-ranging mobility characteristic of Paleolithic big-game hunting, favouring longer stays at productive sites.

Why ''first step'' rather than achievement: true full sedentism, associated with year-round permanent settlement, storage and eventually agriculture/animal husbandry, is a Neolithic-era development (e.g., Mehrgarh in the Indus region, and later Indian Neolithic sites like Koldihwa/Mahagara in the Belan valley); Mesolithic communities remained substantially foraging-based, with only incipient, localized and seasonal sedentary tendencies rather than the year-round permanent villages of the Neolithic.

Conclusion: the Mesolithic represents the crucial first step -- via resource-rich riverine settlement, repeated site-reuse and reduced residential mobility -- toward eventual sedentary life, without itself constituting full sedentism, which was achieved only with Neolithic domestication and permanent village agriculture.', 'The answer should explicitly frame the Mesolithic as transitional (''first step'') rather than claiming it achieved full sedentism outright, and should cite specific sites (Bagor, Sarai Nahar Rai/Mahadaha) as evidence alongside a Neolithic contrast (Mehrgarh, Koldihwa) to show where true sedentism actually emerges.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section A, Q3(b). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('77d9a38e-fc43-4335-9c4e-607ce26c6474', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 11, 'A', '3(c)', 15, 250, 'Critically examine the impact of modern democratic institutions on contemporary tribal societies. Illustrate with suitable ethnographic examples.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('77d9a38e-fc43-4335-9c4e-607ce26c6474', 'Modern democratic institutions -- the Constitution, Panchayati Raj, electoral politics, judiciary -- have transformed tribal societies'' political and social organization since independence, with genuinely mixed consequences.

Positive impacts: reservation of seats in Parliament/State legislatures and Panchayats for Scheduled Tribes has enabled unprecedented tribal political representation and voice; the Panchayats (Extension to Scheduled Areas) Act, 1996 formally recognizes Gram Sabhas in Fifth Schedule areas with authority over customary resources, land and minor forest produce, partially reconciling customary tribal self-governance with the modern Panchayati Raj framework (though implementation is uneven, as documented among Gond and Baiga communities in Madhya Pradesh/Chhattisgarh); the Forest Rights Act, 2006, itself a product of democratic mobilization, has extended individual and community forest-rights recognition to many forest-dwelling communities.

Negative/disruptive impacts: electoral politics has sometimes fractured traditional consensus-based tribal governance (village councils, headmen systems) by introducing party-political competition and factionalism, documented among Naga village-council systems under pressure from party politics; democratic institutions have in some contexts been used to legitimize land acquisition and displacement (dam and mining projects approved through formal but tribal-marginalizing consultation processes) despite constitutional safeguards; ethnic/identity-based political mobilization has occasionally fuelled inter-community conflict, as in the 2023 Manipur violence between the Meitei and Kuki-Zomi communities, partly triggered by contested Scheduled Tribe status claims.

Conclusion: modern democratic institutions have expanded tribal political representation and (unevenly) codified customary rights, but their interface with traditional tribal governance and identity politics has also generated genuine disruption and conflict, showing democratization''s impact on tribal societies as substantively double-edged rather than uniformly beneficial.', 'PESA (1996) and the Forest Rights Act (2006) are the essential named legal-institutional anchors; citing the 2023 Manipur Meitei-Kuki conflict as a concrete, current ethnographic-political illustration of democratic institutions'' disruptive potential is expected for a ''critically examine'' answer.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section A, Q3(c). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('d1c1204f-895d-4062-b940-49af1f9833ed', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 12, 'A', '4(a)', 20, 350, 'Elucidate the problems faced by Particularly Vulnerable Tribal Groups and the major challenges in the formulation of special programmes for their development.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('d1c1204f-895d-4062-b940-49af1f9833ed', 'Introduction: Particularly Vulnerable Tribal Groups (PVTGs, 75 groups identified across 18 states/UTs, formerly termed Primitive Tribal Groups) are a sub-category of Scheduled Tribes identified by criteria including pre-agricultural technology, low literacy, stagnant/declining population, and extreme economic backwardness.

Problems faced: (i) demographic vulnerability -- several PVTGs (Great Andamanese, Onge, Jarawa, Sentinelese) have critically small and, in some cases, declining populations, raising survival concerns; (ii) health -- high infant/maternal mortality, malnutrition, susceptibility to introduced diseases (historically devastating for isolated groups like the Andamanese), and poor healthcare access due to remote habitation; (iii) livelihood insecurity -- continued dependence on shifting cultivation, hunting-gathering or forest produce collection amid shrinking forest access, land alienation and restricted mobility; (iv) educational and literacy deficits, compounded by language barriers (many PVTG languages lack mainstream educational materials) and high dropout rates; (v) cultural erosion -- external contact, tourism (controversially, ''human safari'' tourism affecting the Jarawa) and assimilationist pressure threaten distinct cultural practices and identity; (vi) displacement risk from development/conservation projects overlapping PVTG habitats.

Challenges in programme formulation: (i) the extreme diversity among PVTGs (some semi-nomadic hunter-gatherers, others settled shifting cultivators) makes uniform, one-size-fits-all schemes ineffective, demanding group-specific micro-planning; (ii) balancing protection/isolation (to prevent cultural disruption and disease exposure, as with the Sentinelese) against development/integration (education, healthcare access) creates a genuine policy dilemma without easy resolution; (iii) poor baseline data and periodic Census undercounting of small, remote PVTG populations hampers accurate needs assessment; (iv) weak inter-departmental coordination between tribal welfare, forest, health and education administrations; (v) low PVTG participation in scheme design due to communication/literacy barriers, undermining genuine community ownership; (vi) inadequate, often centrally-designed budgetary allocation under schemes like the Development of PVTGs scheme failing to reach the last-mile due to weak field administration in remote habitats.

Conclusion: PVTGs'' extreme vulnerability -- demographic, economic, cultural and health-related -- demands genuinely differentiated, community-specific programme design, but persistent data gaps, the isolation-versus-integration dilemma and weak field implementation continue to undermine effective policy delivery for this most vulnerable stratum of India''s tribal population.', 'Naming specific PVTGs (Sentinelese, Jarawa, Great Andamanese) and the isolation-vs-integration policy dilemma these cases starkly illustrate is the expected substantive anchor distinguishing a strong answer from a generic tribal-welfare listing.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section A, Q4(a). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('0c8bcaa2-5071-481c-a1d6-bb798eea24a9', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 13, 'A', '4(b)', 15, 250, 'Critically compare Risley''s and Sarkar''s approaches to the classification of peoples of India.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('0c8bcaa2-5071-481c-a1d6-bb798eea24a9', 'Herbert Risley, a colonial ethnographer, classified the peoples of India (The People of India, 1908) primarily using anthropometric criteria -- physical measurements including the nasal index (ratio of nasal breadth to height), stature, cephalic index and other cranio-facial measurements -- proposing seven broad racial types (Turko-Iranian, Indo-Aryan, Scytho-Dravidian, Aryo-Dravidian, Mongolo-Dravidian, Mongoloid, Dravidian) and controversially correlating the nasal index with caste status, effectively naturalizing caste hierarchy as biologically/racially determined -- a methodologically and ideologically colonial-racialist project since discredited.

Sarkar''s approach: Sunit Kumar Sarkar (mid-20th century Indian physical anthropologist) shifted classification toward serological/genetic criteria -- blood group systems (ABO, Rh, MN) and other biochemical genetic markers -- alongside somatometric measures, identifying population types (Mediterranean, Alpine/Armenoid, Nordic, Mongoloid, Negrito, Proto-Australoid) based on genetic-population-distance analysis rather than external phenotype alone, representing a more objective, statistically-grounded approach less directly entangled with justifying social hierarchy.

Critical comparison: Risley''s approach was scientifically weaker (relying on superficial, environmentally-plastic anthropometric traits) and ideologically compromised by its colonial caste-race conflation; Sarkar''s serological approach was methodologically more rigorous and better aligned with genetics as understood by his time, though it too inherited some racial-typological assumptions (discrete population ''types'') that later population genetics (emphasizing clinal, continuous variation rather than discrete races) would further critique. Both approaches, despite their methodological differences, shared the now-outdated assumption that discrete racial ''types'' meaningfully describe Indian population diversity, an assumption modern population genetics has substantially revised.

Conclusion: Sarkar''s serological method represented a genuine methodological advance over Risley''s colonial-era anthropometry, but both remain superseded by contemporary genomic population-genetics approaches that reject discrete racial typologies altogether.', 'Risley''s nasal-index-to-caste correlation and its colonial-ideological function must be explicitly critiqued, not merely described; Sarkar''s serological (blood-group) method should be named specifically as the key methodological contrast.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section A, Q4(b). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('d4590dc8-1373-4aec-8527-51a73e0eb8a6', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 14, 'A', '4(c)', 15, 250, 'Is caste mobility a recent phenomenon? Discuss in the light of Indological and Empirical context.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('d4590dc8-1373-4aec-8527-51a73e0eb8a6', 'Caste mobility -- change in a caste or sub-caste group''s relative rank/status within the local hierarchy -- is not a recent phenomenon, though its pace, mechanisms and visibility have changed significantly over time.

Indological/historical evidence: textual and historical sources (Puranic literature, epigraphic records, dynastic histories) document numerous historical instances of castes/lineages rising in status by claiming higher varna affiliation, adopting Kshatriya or Brahmin genealogical claims, or through royal patronage -- M.N. Srinivas''s own Sanskritization framework was explicitly built on the observation that such status-mobility processes have operated across Indian history, not merely in the modern period; historical dynasties of tribal or otherwise non-elite origin (several regional ruling lineages) are documented to have achieved Kshatriya status through Sanskritizing genealogical and ritual claims well before colonial rule.

Empirical/modern evidence: 20th-century fieldwork (Srinivas''s Coorg study, subsequent village studies) empirically documented ongoing caste mobility through Sanskritization, economic advancement (land acquisition, new occupations), education, political mobilization and affirmative-action-driven status assertion (reservation policy enabling some SC/ST/OBC groups to convert economic/political gains into enhanced social standing) -- accelerating and diversifying mobility mechanisms beyond purely ritual emulation to include constitutional/political routes unavailable in the pre-modern period.

Conclusion: caste mobility is a long-standing structural feature of the Indian caste system evidenced across both historical/Indological and modern empirical record, but modern India''s democratic, educational and constitutional mechanisms have added genuinely new -- and in important respects faster and more assured -- channels of mobility beyond the older ritual-emulation route.', 'The answer should draw on both textual/historical (Indological) evidence of pre-modern caste mobility and modern fieldwork/reservation-policy evidence (empirical) as the question explicitly demands both, concluding that mobility is old but its modern mechanisms are genuinely new/expanded.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section A, Q4(c). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('735b11eb-9e5a-4cec-a498-31304734b7c0', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 15, 'B', '5(a)', 10, 150, 'Scheduled areas');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('735b11eb-9e5a-4cec-a498-31304734b7c0', 'Scheduled Areas are tribal-majority regions specially designated under the Fifth Schedule of the Constitution (applicable to most tribal-concentration states other than the Northeast) for enhanced administrative protection of tribal land, customary law and welfare.

Mechanism: the President, in consultation with the state Governor, declares and can modify Scheduled Areas; the Governor is empowered to make regulations governing land transfer, money-lending and other matters affecting tribal welfare in these areas, and must submit an annual report to the President on their administration; the Governor may also direct that a particular central or state law not apply, or apply with modifications, to a Scheduled Area.

Distinction from Sixth Schedule: Sixth Schedule areas (Assam, Meghalaya, Tripura, Mizoram) instead have Autonomous District/Regional Councils with their own legislative, judicial and executive powers -- a stronger form of self-governance than the Fifth Schedule''s Governor-mediated protective-regulatory model.

Significance: Scheduled Areas, together with the Panchayats (Extension to Scheduled Areas) Act 1996, form the core constitutional-administrative framework protecting tribal land alienation, customary governance and resource rights in mainland tribal-belt India.', 'The Fifth vs Sixth Schedule distinction (Governor-regulation model vs Autonomous District Councils) is the key comparative point examiners expect, not just a definition of Fifth Schedule areas alone.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section B, Q5(a). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('6467a382-b466-4821-9f0f-83af79f6495a', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 16, 'B', '5(b)', 10, 150, 'Ramapithecus-Sivapithecus debate');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('6467a382-b466-4821-9f0f-83af79f6495a', 'Ramapithecus (fossils from the Siwalik hills, South Asia) was initially interpreted by G.E. Lewis (1930s) and later strongly championed by Elwyn Simons and David Pilbeam in the 1960s-70s as a direct early hominid ancestor, based on dental features (thick enamel, reduced canines, parabolic dental arcade) seemingly resembling later hominins more than apes.

The debate: this hominid-ancestor interpretation dominated for decades, but subsequent fossil discoveries and, crucially, molecular/biochemical evidence (Sarich and Wilson''s immunological/molecular-clock studies in the 1960s-70s, later DNA-based estimates) showed the human-ape lineage split occurred much more recently (roughly 5-8 million years ago) than Ramapithecus''s dated age (c. 12-14 million years) would allow if it were a true hominid ancestor. Further, more complete facial/cranial fossils recovered in the late 1970s-80s revealed that Ramapithecus''s actual skull morphology closely resembled Sivapithecus, itself now recognized as an ancestor of the modern orangutan (Pongo) lineage rather than of humans.

Resolution: Ramapithecus was subsequently reclassified as a female/smaller specimen of Sivapithecus, resolving the debate in favour of an Asian-great-ape (orangutan) ancestry rather than a human-ancestor status, and serving as a landmark case demonstrating molecular/biochemical evidence overturning purely morphology-based paleoanthropological interpretation.', 'The key resolution point -- molecular-clock evidence (Sarich-Wilson) contradicting the hominid-ancestor dating, followed by fossil re-evaluation reclassifying Ramapithecus under Sivapithecus/orangutan ancestry -- is the specific content expected, not just a description of the fossils themselves.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section B, Q5(b). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('ee228a96-1bcc-4402-81bb-dbe65fdcffac', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 17, 'B', '5(c)', 10, 150, 'Village as little republic');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('ee228a96-1bcc-4402-81bb-dbe65fdcffac', 'The characterization of the Indian village as a ''little republic'' originates from colonial administrator-scholars (notably Charles Metcalfe, 1830) who described villages as largely self-sufficient, self-governing communities -- economically autonomous (through jajmani-based internal exchange) and politically managed by their own panchayats, seemingly unaffected by the rise and fall of larger kingdoms and empires around them.

Critical assessment: this image has been substantially revised by later ethnographic/sociological research (M.N. Srinivas, Louis Dumont, F.G. Bailey) which showed villages were never fully isolated or internally undifferentiated ''republics'' -- they were, and are, internally stratified by caste hierarchy, unequal landholding and gender, with power concentrated in dominant castes rather than democratically distributed; villages were also always embedded in wider regional economic, political and religious networks (pilgrimage circuits, regional kingdoms'' revenue systems, inter-village marriage networks) rather than truly self-contained.

Significance: the ''little republic'' image, though a colonial-administrative romanticization used partly to justify indirect rule through village-level structures, nonetheless correctly identified real elements of village-level self-governance (panchayats, jajmani exchange) later formalized institutionally in India''s post-independence Panchayati Raj system.', 'A strong answer must critique the romanticized ''little republic'' image (Metcalfe''s colonial framing) using later ethnographic evidence of internal caste stratification and external embeddedness (Srinivas, Dumont), not simply restate the description approvingly.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section B, Q5(c). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('5e19aa4b-2981-4059-a3e5-45116e0e6b60', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 18, 'B', '5(d)', 10, 150, 'Dravidian languages and their subgroups');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('5e19aa4b-2981-4059-a3e5-45116e0e6b60', 'The Dravidian language family, spoken predominantly across southern India (plus pockets in central/eastern India and Brahui in Pakistan/Afghanistan), comprises roughly 80 languages spoken by over 200 million people, and is conventionally classified into four subgroups: South Dravidian (Tamil, Malayalam, Kannada, Tulu, and several tribal languages like Toda, Kota), South-Central Dravidian (Telugu, Gondi, Kui, Konda), Central Dravidian (Kolami, Parji, Ollari), and North Dravidian (Kurukh, Malto, and the geographically isolated Brahui).

Significance: the four major literary languages (Tamil, Telugu, Kannada, Malayalam) have long, independent classical literary traditions, with Tamil-Brahmi inscriptions (c. 2nd century BCE) among the earliest attested Dravidian writing; several tribal Dravidian languages (Gondi, Kurukh, Kui) remain primarily oral, spoken by central-Indian tribal communities and increasingly endangered.

Broader debate: the Dravidian family''s origins and relationship to the Indus Valley Civilization''s undeciphered script remain contested and unresolved, with some scholars proposing a Dravidian-Harappan linguistic connection, making Dravidian linguistic classification directly relevant to ongoing debates about South Asian population and language history.', 'The four-subgroup classification (South, South-Central, Central, North) with at least one named language per subgroup is the core expected content; noting Brahui''s geographic isolation in Pakistan/Afghanistan is a frequently-tested specific detail.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section B, Q5(d). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('caaaba56-5e3b-418c-b271-f13242181888', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 19, 'B', '5(e)', 10, 150, 'Karma and rebirth');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('caaaba56-5e3b-418c-b271-f13242181888', 'Karma and rebirth (samsara) are foundational, interlinked concepts across Indian religious traditions (Hinduism, Buddhism, Jainism), explaining moral causation and the cycle of existence beyond a single lifetime.

Karma: the principle that intentional actions (of body, speech, mind) generate consequences that shape an individual''s future circumstances, understood in Hindu thought as accumulated across lifetimes (sanchita, prarabdha, kriyamana karma categories) and in Buddhism as an impersonal causal law of moral consequence rather than externally-administered divine judgment.

Rebirth: the doctrine that the consequences of karma are worked out across successive lives, with the specific form/circumstances of rebirth determined by one''s accumulated karmic balance; Hindu philosophy generally posits a persisting atman (soul) undergoing rebirth, whereas Buddhism explicitly denies a permanent self (anatta), instead describing a causally-linked stream of consciousness continuing without a fixed, unchanging soul.

Anthropological relevance: karma-rebirth beliefs function as powerful social-legitimation and moral-regulation mechanisms, historically used to explain and rationalize caste-based social position and inequality (present birth-status as the fruit of past-life karma) while also providing an ethical framework motivating moral conduct and, in the pursuit of moksha/nirvana, ultimate liberation from the cycle altogether.', 'The Hindu (persisting atman) vs Buddhist (anatta, no permanent self) distinction in how rebirth is understood is the key comparative-religion point expected; the caste-legitimation social function of karma doctrine is the anthropologically relevant critical dimension.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section B, Q5(e). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('77502818-3428-403c-a555-abee1ad52927', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 20, 'B', '6(a)', 20, 350, 'Is annihilation of caste possible? Discuss the future of caste system in the light of various proactive measures taken by the Indian State.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('77502818-3428-403c-a555-abee1ad52927', 'Introduction: B.R. Ambedkar''s Annihilation of Caste (1936) remains the foundational text framing this question -- he argued caste could not be reformed piecemeal but required the destruction of its religious-scriptural sanction (rejecting Chaturvarna itself, not merely its abuses), a position that puts a hard, still-unresolved question before any assessment of caste''s future: is genuine annihilation achievable, or only mitigation?

Proactive state measures: (i) constitutional abolition of untouchability (Article 17) and prohibition of caste discrimination (Article 15); (ii) reservation policy in education, employment and legislatures for SCs/STs (and later OBCs, per the Mandal Commission) as compensatory-mobility measures; (iii) the SC/ST (Prevention of Atrocities) Act, 1989 criminalizing caste-based violence; (iv) land reforms intended to break caste-linked land monopolies; (v) inter-caste marriage incentive schemes and Dalit welfare/scholarship programmes.

Assessment of impact: these measures have produced genuine, measurable mobility -- a substantial Dalit and OBC political class, growing middle class, greater political representation -- but have not eliminated caste as a lived social reality; caste continues to structure marriage (overwhelming endogamy persists even among urban, educated Indians), residential patterns, and informal social discrimination, while caste-based violence (atrocities against Dalits) persists despite legal prohibition, and caste has if anything become more, not less, salient in electoral mobilization and identity politics.

Structural obstacles to annihilation: caste''s embeddedness in religious sanction, its function as an endogamous marriage-network resource, its persistence as a vehicle for democratic political mobilization and vote-bank politics, and continued economic stratification along caste lines all work against full annihilation, even as individual caste practices attenuate.

Conclusion: the Indian State''s proactive measures have substantially reformed caste''s grosser inequalities and expanded mobility channels envisioned neither by pure Sanskritization nor untouched tradition, but full ''annihilation'' in Ambedkar''s radical sense -- the complete dissolution of caste as a social category -- remains unrealized; caste''s future is more plausibly one of continued attenuation, transformation and politicization than outright disappearance.', 'Ambedkar''s specific Annihilation of Caste argument (destroying scriptural sanction, not just reforming abuses) must be stated as the conceptual benchmark against which state measures are then assessed; the answer should conclude with a reasoned, non-evasive position (attenuation/transformation rather than full annihilation) rather than remaining purely descriptive.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section B, Q6(a). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('862869d0-bf02-4753-b8c4-d4889f1d0e82', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 21, 'B', '6(b)', 15, 250, 'Distinguishing between ethnic identity and ethnicity, discuss the factors responsible for ethnic conflict in tribal areas.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('862869d0-bf02-4753-b8c4-d4889f1d0e82', 'Ethnic identity is the subjective, self-ascribed sense of belonging to a group defined by shared ancestry, language, religion or culture -- an internally-felt, often situational and negotiable identification. Ethnicity, following Fredrik Barth''s influential boundary-approach, is better understood as the social process of maintaining group boundaries through interaction and differentiation from other groups, rather than a fixed inventory of cultural traits -- ethnicity exists relationally, produced and reproduced at the boundary between groups, while ethnic identity is the individual/psychological dimension of belonging to a side of that boundary.

Factors causing ethnic conflict in tribal areas: (i) competition over scarce resources -- land, forest, minerals -- between tribal groups themselves or between tribal and non-tribal/migrant settler populations; (ii) contested claims to Scheduled Tribe status or its associated benefits (reservation, land protection), as seen in the 2023 Meitei-Kuki conflict in Manipur, where the Meitei community''s demand for ST status was fiercely opposed by Kuki-Zomi groups fearing dilution of their existing protections and resources; (iii) political mobilization along ethnic lines for electoral advantage, hardening group boundaries; (iv) historical grievances from colonial-era boundary-drawing and unequal development across different tribal communities; (v) demographic change from migration altering the ethnic balance in a region, perceived as threatening by established communities; (vi) weak or partisan state mediation, which can inflame rather than resolve boundary disputes.

Conclusion: ethnic conflict in tribal areas typically arises where Barth-style boundary competition intersects with material resource scarcity and state-mediated status/benefit allocation, as starkly illustrated by the ongoing Manipur conflict.', 'Barth''s boundary-maintenance theory is the standard theoretical anchor for the ethnicity/ethnic-identity distinction; the 2023 Manipur Meitei-Kuki conflict is the specific, current and clearly expected illustrative example for the conflict-factors half.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section B, Q6(b). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('dc569e7f-3390-46b1-a24c-d178fc9844b4', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 22, 'B', '6(c)', 15, 250, '"Siwalik deposits show a variety of Neogene fossil primates." Critically examine.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('dc569e7f-3390-46b1-a24c-d178fc9844b4', 'The Siwalik Hills (foothills of the Himalayas spanning Pakistan, India, Nepal) preserve an exceptionally rich and long (spanning much of the Neogene, roughly 23-2.6 million years ago) fossil-bearing sedimentary sequence, making the claim substantively accurate -- the Siwaliks are indeed among the world''s most important Neogene primate fossil localities.

Key primate fossils: Sivapithecus (large-bodied hominoid, dated roughly 12.5-8.5 million years ago, now firmly established via craniofacial evidence as an ancestor of the modern orangutan lineage rather than of humans, resolving the earlier Ramapithecus-Sivapithecus confusion); various cercopithecoid (Old World monkey) fossils documenting the diversification of monkey lineages through the Neogene; and other hominoid remains contributing to understanding ape evolution and biogeography in Miocene Asia.

Critical examination: while the diversity and richness of Siwalik primate fossils is genuinely well-established, several qualifications are necessary -- (i) precise stratigraphic dating and correlation across different Siwalik exposures remains methodologically challenging, given the sequence''s considerable geographic spread and tectonic disturbance; (ii) many fossils are fragmentary (isolated teeth, jaw fragments), limiting confident taxonomic and phylogenetic assignment; (iii) taxonomic classification of the Sivapithecus-related hominoid material has itself been repeatedly revised as new material and analytical methods (including molecular-clock cross-checks) became available, indicating ongoing scientific uncertainty rather than settled consensus; (iv) the Siwalik record, while rich, is geographically limited to South Asia and cannot alone resolve broader questions of ape/hominin biogeographic dispersal across Africa and Eurasia.

Conclusion: the Siwalik deposits do substantiate a genuine diversity of Neogene fossil primates, most significantly Sivapithecus''s contribution to resolving orangutan ancestry, but ongoing dating, fragmentary-fossil and taxonomic uncertainties mean the record should be examined critically rather than treated as a fully settled evolutionary account.', 'Sivapithecus''s resolved orangutan-ancestor status (connecting directly to the Ramapithecus-Sivapithecus debate tested elsewhere on this paper) is the central named fossil expected; the ''critically examine'' instruction requires flagging dating/fragmentary-evidence limitations, not just listing fossil diversity approvingly.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section B, Q6(c). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('7e28f66d-3eb4-4120-8b1f-4916d4f14018', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 23, 'B', '7(a)', 20, 350, 'Elucidate the shifting terrains of India''s tribal policies in colonial and post-colonial periods.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('7e28f66d-3eb4-4120-8b1f-4916d4f14018', 'Introduction: Indian tribal policy has shifted substantially across the colonial and post-colonial periods, moving through phases of exploitative penetration, protective isolation, integrationist development, and finally rights-based autonomy.

Colonial period -- early exploitation (pre-1857): British expansion, revenue settlement and commercial penetration into tribal areas caused large-scale land alienation, forest restriction and exploitation by non-tribal moneylenders/traders, provoking major tribal rebellions -- the Santhal Hul (1855-56) and later the Munda Ulgulan led by Birsa Munda (1899-1900) -- both explicitly protesting land alienation and colonial/zamindari oppression.

Colonial period -- protective isolation (post-1857): chastened by these rebellions, the colonial state shifted toward creating ''Excluded'' and ''Partially Excluded Areas'' under the Government of India Act, 1935, restricting non-tribal entry and administering tribal areas indirectly through separate regulation -- a paternalistic protection regime that nonetheless kept tribal areas administratively and educationally isolated from mainstream development.

Post-independence -- integration and the Elwin-Ghurye debate: independent India''s Constitution created the Fifth and Sixth Schedules, institutionalizing a ''via media'' between Verrier Elwin''s protective-isolationist leanings and G.S. Ghurye''s integrationist ''backward Hindu'' assimilation position -- Nehru''s own ''Panchsheel'' for tribal policy (development without imposing external values, respecting tribal land/culture, training tribals to administer their own affairs, avoiding over-administration) reflected this deliberate middle path, operationalized through Tribal Sub-Plans, Integrated Tribal Development Agencies, and community development programmes from the 1950s-70s, though often criticized for top-down, insufficiently participatory implementation.

Post-1980s -- rights and autonomy: democratic decentralization and tribal-rights movements shifted policy toward statutory recognition of self-governance and resource rights -- PESA (1996) extending Panchayati Raj with Gram Sabha primacy to Fifth Schedule areas, the Forest Rights Act (2006) recognizing individual and community forest rights, and the Land Acquisition, Rehabilitation and Resettlement Act (2013) strengthening consent and compensation safeguards -- representing a genuine shift from state-directed development toward rights-based, community-authored governance, even though implementation gaps (bureaucratic delay, inadequate awareness, resistance from vested interests) persist.

Conclusion: India''s tribal policy terrain has shifted from colonial exploitation and subsequent protective isolation to post-independence integrationist development (the Elwin-Ghurye-shaped ''via media'') and finally toward the still-unfolding, rights-and-autonomy-based framework of PESA and the Forest Rights Act -- each phase responding to the perceived failures of the one before it.', 'The four-phase periodization (colonial exploitation, colonial protective-isolation, post-independence integrationist ''via media'', post-1980s rights/autonomy) with named legal instruments at each stage (Government of India Act 1935 exclusions, Fifth/Sixth Schedule, PESA, Forest Rights Act) is the expected comprehensive structure for full marks at 20 marks.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section B, Q7(a). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('c6166a2b-dda6-4268-ae19-fc8dcd0035f6', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 24, 'B', '7(b)', 15, 250, 'Critically Examine how the displacement of tribal communities due to hydroelectric river dam projects has affected the women in local context. Illustrate with suitable ethnographic Examples.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('c6166a2b-dda6-4268-ae19-fc8dcd0035f6', 'Hydroelectric dam-induced displacement disproportionately burdens tribal women, whose roles, rights and resources are frequently marginalized in both displacement itself and resettlement processes.

Gendered impacts: (i) loss of land and forest-based livelihood -- tribal women, central to subsistence agriculture, minor-forest-produce collection and household food security, typically lose direct access to land and forest resources, since compensation/rehabilitation land titles are usually registered in male household heads'' names, systematically excluding women from formal resettlement entitlements; (ii) increased domestic and unpaid labour burden in unfamiliar resettlement sites lacking accustomed water, fuelwood and food sources; (iii) loss of traditional knowledge-based economic roles (seed selection, forest-produce processing) that had given women a measure of economic autonomy within tribal households; (iv) heightened vulnerability to sexual harassment, trafficking and domestic violence in disrupted, insecure resettlement conditions, documented in studies of Sardar Sarovar (Narmada) oustee communities among Bhil and Bhilala women; (v) erosion of women''s traditional decision-making roles and community standing as displacement fragments existing social-support and kinship networks.

Ethnographic illustration: studies of the Narmada Bachao Andolan-documented displacement (Sardar Sarovar dam) show tribal women organizing prominently in resistance movements precisely because they bore displacement''s heaviest burden, while government-commissioned studies of Odisha''s Hirakud and Balimela dam oustees similarly document women''s exclusion from land-title-based compensation.

Conclusion: hydroelectric displacement''s gendered impact on tribal women -- compounding loss of livelihood, land-title exclusion and heightened vulnerability -- demands gender-disaggregated resettlement policy (joint or women''s-name land titling, women-inclusive rehabilitation planning) that current compensation frameworks have largely failed to provide.', 'The land-title-registered-in-male-name mechanism excluding women from formal compensation is the single most important specific point; citing the Narmada/Sardar Sarovar displacement and Bhil/Bhilala women''s documented experience gives the required concrete ethnographic illustration.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section B, Q7(b). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('c08a1c1a-efd5-416a-8f0c-f28f69170981', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 25, 'B', '7(c)', 15, 250, 'Elucidate the role of anthropology in nation building. Illustrate with suitable examples.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('c08a1c1a-efd5-416a-8f0c-f28f69170981', 'Anthropology has contributed substantively to Indian nation-building since independence by supplying the empirical, culturally-grounded knowledge needed to integrate a vastly diverse population into a shared political and developmental framework.

Policy formulation: anthropological fieldwork directly shaped tribal policy (Verrier Elwin''s ethnographic advocacy influencing Nehru''s Panchsheel approach to tribal administration) and continues to inform PVTG development schemes, land and forest-rights legislation, and Scheduled Area administration grounded in actual community practice rather than abstract assumption.

Development planning and evaluation: applied anthropological studies -- L.P. Vidyarthi''s studies of the social impact of industrialization and dam-building on Bihar''s tribal communities, N.K. Bose''s studies of Partition-refugee resettlement in West Bengal, and M.N. Srinivas-associated famine and rural-development studies -- have directly informed government understanding of development''s social costs and the design of rehabilitation/welfare measures.

National integration: ethnographic documentation of India''s linguistic, religious and caste diversity (the Anthropological Survey of India''s People of India project, mapping thousands of communities) has provided the empirical basis for reorganizing states along linguistic lines, designing affirmative-action categories (SC/ST/OBC classification) and formulating minority and linguistic-rights protections central to India''s federal, plural constitutional design.

Social cohesion and conflict resolution: anthropological understanding of ethnic-identity dynamics informs conflict-mediation efforts in situations of communal or ethnic tension (Northeast insurgency contexts, caste/communal conflict), while documentation of syncretic and shared cultural practices supports policy narratives of unity-in-diversity.

Conclusion: from tribal policy and development planning to state reorganization and conflict mediation, anthropology''s empirical, ground-level understanding of India''s social diversity has been directly instrumental to the practical work of building and sustaining a genuinely plural Indian nation.', 'Naming specific applied studies (Vidyarthi on Bihar dam displacement, Bose on refugee resettlement, Elwin''s influence on Nehru''s tribal Panchsheel) rather than a generic ''anthropology helps understand diversity'' claim is the expected concrete substantiation.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section B, Q7(c). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('2c595a27-a07b-4e1c-b541-a16322d5194d', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 26, 'B', '8(a)', 20, 350, 'Discuss the distribution of tribes in different geographical regions of India. Identify the distinct institutional features of tribal societies of these regions.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('2c595a27-a07b-4e1c-b541-a16322d5194d', 'Introduction: India''s roughly 700+ Scheduled Tribe communities (over 10 crore population per Census 2011, about 8.6% of India''s total population) are distributed across four broad geo-cultural zones, each showing distinct racial/physical affinity, subsistence pattern and institutional organization.

North and North-Eastern zone: spans the Himalayan belt and the entire Northeast (Nagaland, Mizoram, Meghalaya, Manipur, Arunachal Pradesh, Tripura, Sikkim); tribes here (Naga groups, Mizo, Khasi, Garo, Bhutia, Lepcha) generally show Mongoloid physical affinity, practice a mix of settled agriculture and shifting (jhum) cultivation, and are notable for distinct institutional features -- strong village-council-based self-governance (Naga village councils), several matrilineal descent/inheritance systems (Khasi, Garo, uniquely prominent among world matrilineal societies), and generally higher literacy and Christian religious conversion rates than other tribal zones, alongside historically strong ethnic-political autonomy movements.

Central/Middle Indian zone: the largest tribal-population zone, spanning Madhya Pradesh, Chhattisgarh, Jharkhand, Odisha, and adjoining parts of Maharashtra/Andhra Pradesh/West Bengal; tribes (Gond, Santhal, Munda, Ho, Oraon, Bhil, Baiga, Kondh) show predominantly Proto-Australoid physical affinity, depend heavily on forest resources and subsistence agriculture, and institutionally are marked by clan/totemic organization, village-headman (mahato/pradhan/manki-munda) based governance, and historically significant land-alienation-driven rebellions (Santhal Hul, Munda Ulgulan) that directly shaped colonial and post-colonial tribal protective legislation.

Southern zone: covers the Western Ghats and hill tracts of Kerala, Tamil Nadu, Karnataka, Andhra Pradesh (Toda, Kadar, Irula, Chenchu, Kurumba); generally smaller, more geographically confined populations showing Dravidian/Proto-Australoid affinity, historically forest-dependent hunter-gatherer or pastoral economies (Toda''s distinctive buffalo-pastoralism and polyandrous kinship institution being a notable exception), now substantially affected by plantation economy and tourism-driven change.

Andaman and Nicobar zone: geographically isolated island populations (Great Andamanese, Onge, Jarawa, Sentinelese, Shompen) of Negrito (Andaman) and Mongoloid (Nicobarese) affinity, among the world''s most isolated hunter-gatherer/foraging societies, institutionally organized around small band-level social organization with minimal external contact -- several classified as PVTGs requiring the strongest protective, low-contact administrative approach in India.

Conclusion: India''s tribal geography maps onto four distinct zones -- North-Eastern (Mongoloid, matrilineal/village-council institutions), Central (Proto-Australoid, clan/totemic, land-rebellion history), Southern (Dravidian/Proto-Australoid, smaller forest-dependent groups) and Andaman-Nicobar (Negrito, isolated band societies) -- each with institutional features shaped by distinct racial history, ecology and degree of external contact.', 'The four-zone framework with a named racial/physical-affinity label, subsistence pattern and a distinctive institutional feature (Khasi/Garo matriliny for the Northeast, Santhal/Munda clan-and-rebellion history for Central India, Toda polyandry for the South, PVTG band-isolation for Andaman-Nicobar) per zone is the expected comprehensive structure for 20 marks.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section B, Q8(a). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('32cfe335-c47c-4719-b0ea-9970e070e710', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 27, 'B', '8(b)', 15, 250, 'Critically evaluate the contributions of S.C. Roy to Indian Anthropology?');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('32cfe335-c47c-4719-b0ea-9970e070e710', 'Sarat Chandra Roy (1871-1942), widely regarded as the ''Father of Indian Ethnography,'' pioneered systematic, fieldwork-based ethnographic study of Chota Nagpur''s tribal communities (Munda, Oraon, Kharia, Birhor, Ho) at a time when Indian anthropology was still largely a colonial-administrative enterprise.

Contributions: (i) conducted detailed, empathetic monographic studies -- The Mundas and Their Country (1912), The Oraons of Chota Nagpur (1915), The Birhors (1925) -- combining ethnographic description with attention to tribal customary law, which he leveraged in his parallel career as a lawyer providing legal assistance to tribals in land and customary-rights disputes, directly linking anthropological knowledge to tribal welfare advocacy; (ii) founded and edited Man in India (1921), a still-running journal that became a crucial platform for Indian (not only colonial/foreign) anthropological scholarship, nurturing an indigenous Indian anthropological tradition; (iii) documented tribal religion, totemism, kinship and material culture with unusual ethnographic depth for his period, providing an invaluable historical-baseline record for later comparative and change-focused tribal studies.

Critical limitations: Roy''s work remained substantially descriptive-comparative rather than theoretically innovative -- he did not develop original analytical frameworks comparable to contemporaneous structural-functionalist or culture-historical theory, and his writing at times reflected the evolutionary and racially-inflected vocabulary common to his era (though considerably more sympathetic and less exploitative than colonial administrator-ethnographers). His focus was also geographically concentrated on Chota Nagpur, limiting the generalizability of his specific findings.

Conclusion: Roy''s meticulous, welfare-oriented fieldwork and his founding of Man in India make him a genuinely foundational figure who indigenized Indian anthropology and linked it concretely to tribal legal advocacy, even though his contribution is better assessed as ethnographic-descriptive pioneering than as original theoretical innovation.', 'Naming specific monographs (The Mundas and Their Country, The Oraons of Chota Nagpur) and Man in India''s founding are essential factual anchors; the ''descriptive rather than theoretically original'' critique is the expected balancing element for a ''critically evaluate'' question.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section B, Q8(b). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('d4052365-8406-4903-a71d-f92707121037', '12f0c4d9-ebe3-4e9f-920a-55a5db5be84f', 28, 'B', '8(c)', 15, 250, 'How are Other Backward Classes identified? Enumerating the important features, elucidate the recent changes in their social and economic life.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('d4052365-8406-4903-a71d-f92707121037', 'Other Backward Classes (OBCs) are castes/communities identified as socially and educationally backward, entitled to affirmative-action benefits distinct from SC/ST reservation.

Identification mechanism: the Mandal Commission (Second Backward Classes Commission, 1980 report, implemented 1990) used indicators of social backwardness (castes considered low in traditional social hierarchy, dependent on manual labour), educational backwardness (literacy/school-enrolment gaps relative to state averages), and economic backwardness (occupation, asset ownership) to identify OBC castes, recommending 27% central-government job/education reservation, subsequently upheld with the ''creamy layer'' exclusion by the Supreme Court in Indra Sawhney v. Union of India (1992); the National Commission for Backward Classes (given constitutional status via the 102nd Amendment, 2018) now maintains and periodically revises the Central OBC list, with states maintaining their own separate OBC lists.

Important features: OBCs are not a homogeneous bloc but an extremely heterogeneous aggregation of numerous distinct castes/communities varying widely in actual socio-economic status; the creamy-layer criterion (income/status threshold) excludes the relatively better-off OBC sub-groups from reservation benefits, targeting relief toward the genuinely backward within the category.

Recent changes in social/economic life: political assertion and representation have grown substantially (OBC-based political parties/leadership in several states), reservation has expanded access to government employment, higher education and, since 2019, entry into private unaided institutions in some contexts; economically, agrarian OBC communities have seen mixed outcomes -- some (dominant landholding OBC castes like Jats, Patels, Marathas) demanding further reservation despite relative prosperity, reflecting persistent contestation over who genuinely qualifies as ''backward'' amid ongoing economic and political change.

Conclusion: OBC identification rests on the Mandal Commission''s social-educational-economic criteria formalized through the creamy-layer-qualified reservation regime, with recent decades showing substantial political empowerment alongside continued contestation over the category''s internal heterogeneity.', 'The Mandal Commission (1980/1990), Indra Sawhney (1992) creamy-layer ruling, and the 102nd Amendment''s constitutional status for the NCBC are the three essential legal-institutional anchors; recent dominant-caste reservation-demand movements (Jat/Patel/Maratha agitations) are a strong, contemporary illustration of the category''s internal contestation expected in the ''recent changes'' half.', 'UPSC CSE Mains 2023, Anthropology Optional Paper II, Section B, Q8(c). Question text extracted via pdftotext from a PDF hosted by Vishnu IAS Academy (vishnuias.com/wp-content/uploads/2023/09/UPSC-ANTHROPOLOGY-2023-PAPER-2-MODEL-ANSWERS.pdf), cross-checked word-for-word against Edukemy''s independent full question-paper transcription (edukemy.com) and, for note-writing sub-parts, Anthroholic''s bilingual reproduction (anthroholic.com). No independent scanned-official-PDF mirror of Paper II was located this session (contrast Paper I''s stronger sourcing tier); this file''s own model answer, examiner notes and analysis are original and do not rely on the Vishnu IAS source''s own (unreliable) model answers.');
